module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg        clk;
    reg        resetn;
    reg  [1:0] byteena;
    reg  [15:0] d;
    wire [15:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .resetn(resetn),
        .byteena(byteena),
        .d(d),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // Error counter
    integer errors = 0;
    reg [15:0] expected_q;

    // Task to apply and check
    task apply_and_check(
        input      [1:0]   b_in,
        input      [15:0]  d_in,
        input      [15:0]  exp_q
    );
    begin
        byteena = b_in;
        d       = d_in;
        @(posedge clk);
        #1; // Allow output to update
        if (q !== exp_q) begin
            $display("Mismatch: time=%0t | byteena=%b d=%h | expected_q=%h got_q=%h", 
                     $time, b_in, d_in, exp_q, q);
            errors = errors + 1;
        end
    end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        resetn = 0;
        byteena = 2'b00;
        d = 16'h0000;
        expected_q = 16'h0000;

        // Apply reset
        #12;
        resetn = 1;
        #2;

        // Check reset state
        if (q !== 16'h0000) begin
            $display("Mismatch on reset: expected 0000, got %h", q);
            errors = errors + 1;
        end

        // Test 1: Write both bytes (byteena = 11)
        expected_q = 16'hA55A;
        apply_and_check(2'b11, 16'hA55A, expected_q);

        // Test 2: Write only upper byte (byteena = 10), lower should remain
        expected_q = 16'h125A;
        apply_and_check(2'b10, 16'h1234, expected_q);

        // Test 3: Write only lower byte (byteena = 01), upper should remain
        expected_q = 16'h12CD;
        apply_and_check(2'b01, 16'h89CD, expected_q);

        // Test 4: Write neither byte (byteena = 00), nothing should change
        expected_q = 16'h12CD;
        apply_and_check(2'b00, 16'hFFFF, expected_q);

        // Test 5: Synchronous active-low reset
        resetn = 0;
        expected_q = 16'h0000;
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            $display("Mismatch on sync reset: expected 0000, got %h", q);
            errors = errors + 1;
        end

        resetn = 1;
        @(posedge clk);

        // Test 6: Bounded loop of random-like stimulus
        repeat (5) begin
            reg [1:0] b_rand;
            reg [15:0] d_rand;

            b_rand = $random;
            d_rand = $random;

            if (b_rand[1]) expected_q[15:8] = d_rand[15:8];
            if (b_rand[0]) expected_q[7:0]  = d_rand[7:0];

            apply_and_check(b_rand, d_rand, expected_q);
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
